-- Phase 11: expiring, revocable, usage-limited enrolment invites (QR links) with an enrolment window and optional teacher approval.
-- The secret token is generated by the app and NEVER stored: only its SHA-256 hash is kept, so a database leak cannot be turned into working links.
-- All writes go through the functions below (identity comes from the JWT); tables are read-only to clients.

create table subject_invites (
  invite_id        bigint generated always as identity primary key,
  subject_id       bigint not null references subjects(subject_id) on delete cascade,
  token_hash       text not null unique check (token_hash ~ '^[0-9a-f]{64}$'),
  created_by       bigint not null references teachers(teacher_id),
  created_at       timestamptz not null default now(),
  opens_at         timestamptz not null default now(),
  expires_at       timestamptz not null,
  max_uses         integer not null default 1 check (max_uses between 1 and 1000),
  uses             integer not null default 0 check (uses >= 0),
  require_approval boolean not null default false,
  revoked_at       timestamptz,
  check (expires_at > opens_at),
  check (uses <= max_uses)
);
create index subject_invites_subject_idx on subject_invites (subject_id);

create table enrollment_requests (
  request_id  bigint generated always as identity primary key,
  invite_id   bigint references subject_invites(invite_id) on delete set null,
  subject_id  bigint not null references subjects(subject_id) on delete cascade,
  student_id  bigint not null references students(student_id) on delete cascade,
  status      text not null default 'PENDING' check (status in ('PENDING', 'APPROVED', 'REJECTED')),
  created_at  timestamptz not null default now(),
  decided_at  timestamptz,
  decided_by  bigint references teachers(teacher_id)
);
create unique index enrollment_requests_one_pending on enrollment_requests (subject_id, student_id) where status = 'PENDING';

alter table subject_invites     enable row level security;
alter table enrollment_requests enable row level security;
create policy invites_read  on subject_invites     for select to authenticated using (private.teaches(subject_id) or private.is_admin());
create policy requests_read on enrollment_requests for select to authenticated using (student_id = private.student_id() or private.teaches(subject_id) or private.is_admin());
revoke all on subject_invites, enrollment_requests from anon, authenticated;
grant select (invite_id, subject_id, created_by, created_at, opens_at, expires_at, max_uses, uses, require_approval, revoked_at) on subject_invites to authenticated;   -- not token_hash
grant select on enrollment_requests to authenticated;
grant all on subject_invites, enrollment_requests to service_role;
grant usage on all sequences in schema public to service_role;

create function private.invite_state(i subject_invites) returns text language sql stable as $$
  select case when i.revoked_at is not null then 'REVOKED'
              when now() >= i.expires_at then 'EXPIRED'
              when now() < i.opens_at then 'NOT_OPEN'
              when i.uses >= i.max_uses then 'USED_UP'
              else 'VALID' end $$;

create function create_subject_invite(p_subject_id bigint, p_token_hash text, p_ttl_minutes integer, p_max_uses integer,
                                      p_require_approval boolean default false, p_opens_in_minutes integer default 0)
returns bigint language plpgsql security definer set search_path = public, pg_temp as $$
declare v_tid bigint := private.require_teacher(); v_id bigint;
begin
  if not exists (select 1 from subjects where subject_id = p_subject_id and teacher_id = v_tid) then raise exception 'subject not found' using errcode = 'PT404'; end if;
  if p_token_hash is null or p_token_hash !~ '^[0-9a-f]{64}$' then raise exception 'invalid invite token' using errcode = 'PT422'; end if;
  if p_ttl_minutes is null or p_ttl_minutes not between 5 and 43200 then raise exception 'expiry must be between 5 minutes and 30 days' using errcode = 'PT422'; end if;
  if p_max_uses is null or p_max_uses not between 1 and 1000 then raise exception 'uses must be between 1 and 1000' using errcode = 'PT422'; end if;
  if p_opens_in_minutes is null or p_opens_in_minutes not between 0 and p_ttl_minutes - 1 then raise exception 'the enrolment window must open before the invite expires' using errcode = 'PT422'; end if;
  insert into subject_invites(subject_id, token_hash, created_by, opens_at, expires_at, max_uses, require_approval)
  values (p_subject_id, p_token_hash, v_tid, now() + make_interval(mins => p_opens_in_minutes), now() + make_interval(mins => p_ttl_minutes), p_max_uses, coalesce(p_require_approval, false))
  returning invite_id into v_id;
  perform private.audit('invite.created', 'subject', p_subject_id::text, jsonb_build_object('invite_id', v_id, 'max_uses', p_max_uses, 'ttl_minutes', p_ttl_minutes, 'approval', coalesce(p_require_approval, false)));
  return v_id;
end $$;

create function revoke_subject_invite(p_invite_id bigint) returns void language plpgsql security definer set search_path = public, pg_temp as $$
declare v_tid bigint := private.require_teacher(); i subject_invites%rowtype;
begin
  select * into i from subject_invites where invite_id = p_invite_id for update;
  if not found or not private.teaches(i.subject_id) then raise exception 'invite not found' using errcode = 'PT404'; end if;
  if i.revoked_at is null then
    update subject_invites set revoked_at = now() where invite_id = p_invite_id;
    perform private.audit('invite.revoked', 'subject', i.subject_id::text, jsonb_build_object('invite_id', p_invite_id));
  end if;
end $$;

create function preview_subject_invite(p_token_hash text) returns jsonb language plpgsql stable security definer set search_path = public, pg_temp as $$
declare i subject_invites%rowtype; s subjects%rowtype;
begin
  if private.app_role() is null then raise exception 'login required' using errcode = 'PT403'; end if;
  select * into i from subject_invites where token_hash = p_token_hash;
  if not found then return jsonb_build_object('state', 'NOT_FOUND'); end if;
  select * into s from subjects where subject_id = i.subject_id;
  return jsonb_build_object('state', private.invite_state(i), 'name', s.name, 'section', s.section, 'require_approval', i.require_approval,
    'enrolled', exists (select 1 from enrollments where subject_id = i.subject_id and student_id = private.student_id()),
    'pending', exists (select 1 from enrollment_requests where subject_id = i.subject_id and student_id = private.student_id() and status = 'PENDING'));
end $$;

create function redeem_subject_invite(p_token_hash text) returns jsonb language plpgsql security definer set search_path = public, pg_temp as $$
declare v_sid bigint := private.require_student(); i subject_invites%rowtype; s subjects%rowtype; v_state text;
begin
  select * into i from subject_invites where token_hash = p_token_hash for update;      -- row lock: concurrent redemptions cannot exceed max_uses
  if not found then return jsonb_build_object('outcome', 'NOT_FOUND'); end if;
  select * into s from subjects where subject_id = i.subject_id;
  if exists (select 1 from enrollments where subject_id = i.subject_id and student_id = v_sid) then
    return jsonb_build_object('outcome', 'ALREADY_ENROLLED', 'subject_id', s.subject_id, 'name', s.name, 'section', s.section);   -- consumes no use
  end if;
  v_state := private.invite_state(i);
  if v_state <> 'VALID' then return jsonb_build_object('outcome', v_state); end if;
  if i.require_approval then
    if exists (select 1 from enrollment_requests where subject_id = i.subject_id and student_id = v_sid and status = 'PENDING') then
      return jsonb_build_object('outcome', 'PENDING_APPROVAL', 'subject_id', s.subject_id, 'name', s.name, 'section', s.section);
    end if;
    insert into enrollment_requests(invite_id, subject_id, student_id) values (i.invite_id, i.subject_id, v_sid);
    update subject_invites set uses = uses + 1 where invite_id = i.invite_id;
    perform private.audit('enrollment.requested', 'subject', i.subject_id::text, jsonb_build_object('student_id', v_sid, 'invite_id', i.invite_id));
    return jsonb_build_object('outcome', 'PENDING_APPROVAL', 'subject_id', s.subject_id, 'name', s.name, 'section', s.section);
  end if;
  insert into enrollments(student_id, subject_id) values (v_sid, i.subject_id) on conflict (student_id, subject_id) do nothing;
  update subject_invites set uses = uses + 1 where invite_id = i.invite_id;
  perform private.audit('student.enrolled', 'subject', i.subject_id::text, jsonb_build_object('student_id', v_sid, 'invite_id', i.invite_id));
  return jsonb_build_object('outcome', 'ENROLLED', 'subject_id', s.subject_id, 'name', s.name, 'section', s.section);
end $$;

create function decide_enrollment_request(p_request_id bigint, p_approve boolean) returns text language plpgsql security definer set search_path = public, pg_temp as $$
declare v_tid bigint := private.require_teacher(); r enrollment_requests%rowtype;
begin
  select * into r from enrollment_requests where request_id = p_request_id for update;
  if not found or not private.teaches(r.subject_id) then raise exception 'request not found' using errcode = 'PT404'; end if;
  if r.status <> 'PENDING' then raise exception 'this request was already decided' using errcode = 'PT409'; end if;
  update enrollment_requests set status = case when p_approve then 'APPROVED' else 'REJECTED' end, decided_at = now(), decided_by = v_tid where request_id = p_request_id;
  if p_approve then insert into enrollments(student_id, subject_id) values (r.student_id, r.subject_id) on conflict (student_id, subject_id) do nothing; end if;
  perform private.audit(case when p_approve then 'enrollment.approved' else 'enrollment.rejected' end, 'subject', r.subject_id::text, jsonb_build_object('student_id', r.student_id, 'request_id', p_request_id));
  return case when p_approve then 'APPROVED' else 'REJECTED' end;
end $$;

create function list_enrollment_requests(p_subject_id bigint default null) returns jsonb language plpgsql stable security definer set search_path = public, pg_temp as $$
declare v_tid bigint := private.require_teacher();
begin   -- a pending requester is not enrolled yet, so the teacher cannot read them via RLS; expose only name and roll number
  return coalesce((select jsonb_agg(jsonb_build_object('request_id', r.request_id, 'subject_id', r.subject_id, 'subject', s.name, 'student', st.name,
                                                        'roll_number', st.roll_number, 'created_at', r.created_at) order by r.created_at)
                   from enrollment_requests r join subjects s using (subject_id) join students st using (student_id)
                   where r.status = 'PENDING' and s.teacher_id = v_tid and (p_subject_id is null or r.subject_id = p_subject_id)), '[]'::jsonb);
end $$;

revoke execute on function private.invite_state(subject_invites) from public, anon;
grant  execute on function private.invite_state(subject_invites) to authenticated, service_role;
revoke execute on function create_subject_invite(bigint, text, integer, integer, boolean, integer), revoke_subject_invite(bigint),
  preview_subject_invite(text), redeem_subject_invite(text), decide_enrollment_request(bigint, boolean), list_enrollment_requests(bigint) from public, anon;
grant  execute on function create_subject_invite(bigint, text, integer, integer, boolean, integer), revoke_subject_invite(bigint),
  preview_subject_invite(text), redeem_subject_invite(text), decide_enrollment_request(bigint, boolean), list_enrollment_requests(bigint) to authenticated, service_role;
